/**
 * Multipart. Accepts drag-drop, file picker **and clipboard paste** — paste
is what decides whether support agents actually attach screenshots.

Validated by extension allow-list **and** MIME sniffing — the extension
alone is trivially wrong. EXIF is stripped, the file is virus-scanned, and
it becomes visible only after the scan passes. Stored at
`tickets/{ticketId}/{uuid}`; downloads use short-lived signed URLs and the
bucket is never public.

Limits, all configurable: 10 MB per file, 50 MB and 20 files per ticket.

 * @summary Upload an attachment
 */
export const uploadAttachmentPathTicketIdRegExp = new RegExp('^[A-Z][A-Z0-9]{1,9}-\\d{2}-\\d{5,}$');


export const uploadAttachmentParams = zod.object({
  "ticketId": zod.string().regex(uploadAttachmentPathTicketIdRegExp)
})

export const uploadAttachmentHeader = zod.object({
  "Idempotency-Key": zod.string().uuid().optional().describe('Replaying a key within 24 hours returns the original response instead of\ncreating a second row. Send one on every create — a retried request after\na network timeout is the normal case, not the exception.\n')
})

export const uploadAttachmentBodyIsClientVisibleDefault = false;

export const uploadAttachmentBody = zod.object({
  "file": zod.instanceof(File),
  "isClientVisible": zod.boolean().optional(),
  "commentId": zod.number().optional()
})

/**
 * Hard delete by the uploader within 15 minutes. After that it is a soft
delete leaving a tombstone, so the history still shows something was
attached and removed.

 * @summary Delete an attachment
 */
export const deleteAttachmentPathTicketIdRegExp = new RegExp('^[A-Z][A-Z0-9]{1,9}-\\d{2}-\\d{5,}$');


export const deleteAttachmentParams = zod.object({
  "ticketId": zod.string().regex(deleteAttachmentPathTicketIdRegExp),
  "attachmentId": zod.number()
})

